all_lessons = lessons + rewrites
titles = {path: row['title'] for path, row in by_path.items()}
titles.update({lesson['path']: lesson['title'] for lesson in all_lessons})

def render(lesson):
    for target in lesson['related']:
        assert target in titles, (lesson['path'], target)
    body = '<p>' + prose(lesson['summary']) + '</p>'
    for heading, paragraph in lesson['sections']:
        body += '<h2>' + html.escape(heading) + '</h2><p>' + prose(paragraph) + '</p>'
    body += '<h2>Implementation</h2><pre><code class="language-python">' + html.escape(lesson['code'], quote=False) + '</code></pre>'
    body += '<h2>Performance and operating cost</h2><p>' + prose(lesson['cost']) + '</p>'
    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + prose(item) + '</li>' for item in lesson['mistakes']) + '</ul>'
    body += '<h2>Read next</h2><ul>' + ''.join('<li><a href="/' + path + '">' + html.escape(titles[path]) + '</a></li>' for path in lesson['related']) + '</ul>'
    return body

for index, lesson in enumerate(lessons):
    path = lesson['path']
    assert path not in by_path, path
    subject = 'data-science' if path.startswith('data-science/') else 'machine-learning'
    hub = 'data-science/data-science-for-beginners' if subject == 'data-science' else 'machine-learning/machine-learning-tutorial'
    row = copy.deepcopy(by_path['data-science/getting-started' if subject == 'data-science' else 'machine-learning/getting-started'])
    body = render(lesson)
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'https://aitrove.in/' + path)), path=path,
               title=lesson['title'], summary=lesson['summary'], body=body,
               subject=subject, tags=[subject, path.split('/')[-1]],
               sort_order=7300 + index, published_at=stamp, created_at=stamp, updated_at=stamp)
    row['data'] = {'kind': 'tutorial', 'reading_minutes': max(5, round(len(re.sub(r'<[^>]+>', ' ', body).split()) / 150)),
                   'author_path': 'authors/aitrove-editorial', 'subject_root': hub, 'section_path': hub,
                   'content_format': 'html', 'seo_ready': True,
                   'verification_suite': 'Editorial and API contract review; application data required for snippet execution',
                   'related': [{'path': target, 'title': titles[target]} for target in lesson['related']]}
    rows.append(row)
    by_path[path] = row

for lesson in rewrites:
    row = by_path[lesson['path']]
    row.update(title=lesson['title'], summary=lesson['summary'], body=render(lesson), updated_at=stamp)
    row['data']['reading_minutes'] = max(5, round(len(re.sub(r'<[^>]+>', ' ', row['body']).split()) / 150))
    row['data']['content_format'] = 'html'
    row['data']['seo_ready'] = True
    row['data']['related'] = [{'path': target, 'title': titles[target]} for target in lesson['related']]

for prefix, hub_path, module_title in [
    ('data-science/', 'data-science/data-science-for-beginners', 'Data contracts, analysis and uncertainty'),
    ('machine-learning/', 'machine-learning/machine-learning-tutorial', 'Model validity and decision policy'),
]:
    paths = [lesson['path'] for lesson in lessons if lesson['path'].startswith(prefix)]
    hub = by_path[hub_path]
    hub['data']['modules'].insert(1, {'title': module_title, 'summary': 'Work through one boundary at a time and verify the example against real data.', 'lessons': paths})
    hub['body'] = '<p>' + ('Data science begins with a decision, a population and an observation clock. Learn the shape and quality of the data before making a claim.' if prefix == 'data-science/' else 'Machine learning estimates an outcome from inputs available at a defined decision time. Baselines, splits and operating costs determine whether the model helps.') + '</p><h2>Foundations</h2><ul>' + ''.join('<li><a href="/' + path + '">' + html.escape(titles[path]) + '</a></li>' for path in hub['data']['modules'][0]['lessons']) + '</ul><h2>' + html.escape(module_title) + '</h2><ul>' + ''.join('<li><a href="/' + path + '">' + html.escape(titles[path]) + '</a></li>' for path in paths) + '</ul><h2>Apply the work</h2><ul>' + ''.join('<li><a href="/' + path + '">' + html.escape(titles[path]) + '</a></li>' for path in hub['data']['modules'][-1]['lessons']) + '</ul>'
    hub['summary'] = 'An ordered, practical curriculum from foundations to a checked project.'
    hub['data']['content_format'] = 'html'
    hub['data']['seo_ready'] = True
    hub['updated_at'] = stamp

for lesson in lessons:
    path = lesson['path']
    hub_path = 'data-science/data-science-for-beginners' if path.startswith('data-science/') else 'machine-learning/machine-learning-tutorial'
    anchor_source = 'data-science/core-concepts' if path.startswith('data-science/') else 'machine-learning/core-concepts'
    by_path[anchor_source]['body'] += '<p><strong>Study next:</strong> <a href="/' + path + '">' + html.escape(titles[path]) + '</a>.</p>'

for left, right in [('data-science/practice-project','machine-learning/practice-project'),
                    ('machine-learning/getting-started','data-science/dataset-grain-and-join-cardinality'),
                    ('data-science/getting-started','machine-learning/prediction-time-feature-availability')]:
    by_path[left]['body'] += '<p><strong>Related path:</strong> <a href="/' + right + '">' + html.escape(titles[right]) + '</a>.</p>'

fixture.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'new_lessons': len(lessons), 'rewritten_lessons': len(rewrites), 'total_records': len(rows)}))
